<?php

namespace App\Http\Repositories\Configuraciones;

use Illuminate\Http\Request;
use Illuminate\Support\Collection;
use App\Models\Configuraciones\Archivo;
use App\Http\Repositories\BaseRepository;
use App\Interfaces\Repositorios\ObtenerUnoAvanzado;

class ArchivoRepository extends BaseRepository implements ObtenerUnoAvanzado
{
    /**
     * Constructor.
     *
     * @param Archivo $modelo Modelo de archivos.
     * @return void
     * @author Daniel Beltrán
     */
    public function __construct(Archivo $modelo) {
        parent::__construct($modelo);
    }

    /**
     * Obtener todos los archivos.
     *
     * @param Request $request Contenido de la petición.
     * @return Collection
     * @author Daniel Beltrán
     * @author Andres Gonzalez
     */
    public function getTodo(Request $request): Collection {
        return $this->modelo::select('id', 'modelo', 'modelo_id', 'nombre', 'nombre_original_archivo', 'ruta', 'created_at')
        ->when($request->filled('modelo'), fn($consulta) => $consulta->where('modelo', $request->modelo))
        ->when($request->filled('modelo_id'), fn($consulta) => $consulta->where('modelo_id', $request->modelo_id))
        ->when($request->filled('nombre'), fn($consulta) => $consulta->where('nombre', $request->nombre))
        ->when($request->filled('nombres'), fn($consulta) => $consulta->whereIn('nombre', $request->nombres))
        ->when($request->filled('fecha_creacion_anterior_a'), fn($consulta) => $consulta->whereDate('created_at', '<=', $request->fecha_creacion_anterior_a))
        ->orderBy('created_at', 'DESC')
        ->get();
    }

    /**
     * Obtener el archivo de un modelo específico.
     *
     * @param string $modelo Modelo.
     * @param int $id ID del modelo.
     * @param ?string $nombre Nombre del tipo de archivo.
     * @return ?Archivo
     * @author Daniel Beltrán
     * @deprecated Utilizar getUnoAvanzado() en su lugar.
     */
    public function obtenerPorModelo(string $modelo, int $id, ?string $nombre = null): ?Archivo {
        return $this->modelo::select('id', 'ruta')
        ->where([
            'modelo'    => $modelo,
            'modelo_id' => $id
        ])
        ->when(!is_null($nombre), fn($consulta) => $consulta->where('nombre', $nombre))
        ->first();
    }

    /**
     * Obtener un archivo en base a filtros avanzados.
     *
     * @param Request $request Contenido de la petición.
     * @return ?Archivo
     * @author Daniel Beltrán
     */
    public function getUnoAvanzado(Request $request): ?Archivo {
        return $this->modelo::select('id', 'modelo', 'modelo_id', 'nombre', 'nombre_original_archivo', 'ruta', 'created_at')
        ->when($request->filled('modelo'), fn($consulta) => $consulta->where('modelo', $request->modelo))
        ->when($request->filled('modelo_id'), fn($consulta) => $consulta->where('modelo_id', $request->modelo_id))
        ->when($request->filled('nombre'), fn($consulta) => $consulta->where('nombre', $request->nombre))
        ->when($request->filled('ruta'), fn($consulta) => $consulta->whereLike('ruta', "%{$request->ruta}%"))
        ->first();
    }
}
```

