<?php

namespace App\Http\Controllers\OfertasLaborales;

use Exception;
use Illuminate\Http\Request;
use Illuminate\Http\JsonResponse;
use Illuminate\Support\Facades\DB;
use App\Http\Controllers\Controller;
use Illuminate\Support\Facades\Auth;
use App\Http\Services\OfertasLaborales\ComentarioService;
use App\Http\Repositories\OfertasLaborales\ComentarioRepository;

class ComentarioController extends Controller
{
    /**
     * Constructor.
     *
     * @param ComentarioService $servicio Servicio de comentarios.
     * @param ComentarioRepository $repositorio Repositorio de comentarios.
     * @return void
     * @author Daniel Beltrán
     */
    public function __construct(
        private ComentarioService $servicio,
        private ComentarioRepository $repositorio
    ) {}

    /**
     * Crear un nuevo comentario.
     *
     * @param Request $request Contenido de la solicitud HTTP.
     * @return JsonResponse
     * @author Fahibram Cárcamo
     */
    public function store(Request $request): JsonResponse {
        $codigo    = 201;
        $respuesta = [
            'message' => 'Comentario creado correctamente'
        ];

        try {
            DB::beginTransaction();
            $request->merge(['usuario_id' => Auth::id()]);
            $respuesta['comentario'] = $this->servicio->guardar($request);
            DB::commit();
        } catch (Exception $error) {
            DB::rollBack();

            $codigo    = 400;
            $respuesta = [
                'message' => 'Ocurrió un error',
                'errors'  => $error->getMessage()
            ];
        }

        return new JsonResponse($respuesta, $codigo);
    }
}
