    establecerDatosClassicEditor('comentario_hoja_vida', '');
    $.ajax({
        url: `/comentarios`,
        type: 'POST',
        dataType: 'json',
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            usuario_id: usuario_detalle_id,
            etapa_vacante_usuario_id: etapa_vacante_usuario_id,
            comentario: limpiarHTMLCKEditor(comentario),
        },
        success: function(respuesta) {
            mostrarToast('success', 'Comentario enviado correctamente.');
            $.ajax({
                url: `/comentarios`,
                type: 'GET',
                data: {
                    usuario_id: usuario_detalle_id,
                    vacante_id: VACANTE_ID,
                },
                dataType: 'json',
                success: function(datos) {
                    let comentarios = datos.data || [];
                    $(`#seccion-comentarios-hoja_vida`).empty().append(mostrarSeccionComentarios(comentarios, 'hoja_vida'));
                },
                error: function() {
                    mostrarToast('danger', 'Error al cargar los comentarios.');
                }
            });
        },
        error: function() {
            mostrarToast('danger', 'Error al enviar el comentario.');
        }
    });
}
